function draw(hands){const c=$('#hands');c.width=640;c.height=360;const ctx=c.getContext('2d');ctx.clearRect(0,0,640,360);const edges=[[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17]];for(const h of hands){ctx.strokeStyle='#dcec6b';ctx.lineWidth=2;for(const chain of edges){ctx.beginPath();chain.forEach((v,i)=>ctx[i?'lineTo':'moveTo'](h[v].x*640,h[v].y*360));ctx.stroke()}for(const p of h){ctx.beginPath();ctx.arc(p.x*640,p.y*360,3,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill()}}drawStage(hands)}
$('#record').onclick=()=>{if(!enabled){$('#record-status').textContent='Enable the camera in Explore first.';return}if(recording)return;const participant=$('#participant').value.trim(),session=$('#session').value.trim();if(!participant||!session){$('#record-status').textContent='Enter participant and session IDs.';return}recording={participant,session,label:$('#label').value,frames:[],timestamp:new Date().toISOString()};$('#record-status').textContent='Recording…'};$('#clear').onclick=()=>{records=[];recording=null;$('#record-status').textContent='Recordings cleared.'};$('#download').onclick=()=>{if(!records.length){$('#record-status').textContent='Record at least one sequence first.';return}const blob=new Blob([JSON.stringify({schema_version:1,features:126,sequence_length:32,normalization:'fixed Left/Right slots; wrist xyz absolute; remaining landmarks wrist-relative / wrist-to-middle-mcp distance; missing hand zero',records})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='apex-gestures.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('#connect').onclick=async()=>{if(service){service=null;prediction=null;$('#connect').textContent='Connect trained model';$('#model-status').textContent='Disconnected · rule controls active';return}try{const url=$('#endpoint').value.replace(/\/$/,'');const res=await fetch(url+'/health',{signal:AbortSignal.timeout(5000)});if(!res.ok)throw Error('Service returned '+res.status);const info=await res.json();if(!info.model_loaded)throw Error('Service has no model loaded');service=url;$('#manipulation').value='trained';manipulator.reset();$('#connect').textContent='Disconnect model';$('#model-status').textContent=`Connected · ${info.architecture} · landmark sequences sent to this endpoint`;}catch(e){$('#model-status').textContent='Connection failed: '+e.message+' Browser security may block local HTTP from a hosted page; run the viewer locally or use HTTPS.'}};
async function infer(){serviceBusy=true;try{const res=await fetch(service+'/predict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({frames:windowFrames.map(f=>[...f])}),signal:AbortSignal.timeout(2000)});if(!res.ok)throw Error('Inference '+res.status);prediction=await res.json();predictionAt=performance.now();$('#model-status').textContent=`${prediction.label} · ${(prediction.confidence*100).toFixed(1)}% confidence`;}catch(e){prediction=null;$('#model-status').textContent='Model unavailable; gestures paused. '+e.message}finally{serviceBusy=false}}
window.addEventListener('pagehide',stop);

function setCameraScene(active){cameraActive=active;$('#viewport').classList.toggle('camera-active',active);$('#stage-video').hidden=!active;$('#stage-hands').hidden=!active;ground.visible=!active;gridLines.visible=!active;car.scale.setScalar(active?.8:1.2);car.position.set(0,0,0);manipulator.reset();controls.enablePan=!active;$('#stage-caption').textContent=active?'CAMERA OVERLAY · '+(bundled?'QVIST CONCEPT':'EDUCATIONAL MODEL'):(bundled?'QVIST CONCEPT · CC BY 4.0':'EDUCATIONAL MODEL');$('#gesture-state').textContent=active?'Show your hands · pinch to grab':'Enable camera to bring the car into your view';if(software)renderer.domElement.style.backgroundColor='transparent';}
function applyNatural(hands,sides){const action=manipulator.update(hands,sides);const names={idle:'Hands released / waiting',grab:'GRABBED · move your pinched hand',rotate:'ROTATE · move or turn your open palm',scale:'SCALE · move open hands apart / together',explode:'PULL APART · separate or bring pinches together'};$('#gesture-state').textContent=names[action.mode];auto=false;$('#auto').textContent='↻ Auto orbit';if(action.dx!==undefined){const h=2*camera.position.distanceTo(controls.target)*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)),r=$('#viewport').getBoundingClientRect(),vw=$('#video').videoWidth||640,vh=$('#video').videoHeight||360,fit=Math.min(r.width/vw,r.height/vh),xf=vw*fit/r.width,yf=vh*fit/r.height;const right=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,0),up=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,1);car.position.addScaledVector(right,action.dx*h*camera.aspect*xf).addScaledVector(up,action.dy*h*yf);car.position.clampLength(0,6)}if(action.yaw!==undefined){car.rotation.y+=action.yaw;car.rotation.x=THREE.MathUtils.clamp(car.rotation.x+action.pitch,-1.1,1.1);car.rotation.z=THREE.MathUtils.clamp(car.rotation.z+action.roll,-1.4,1.4)}if(action.scaleRatio)car.scale.setScalar(THREE.MathUtils.clamp(car.scale.x*action.scaleRatio,.25,1.8));if(action.explodeDelta)setExplode(explode+action.explodeDelta);}
function drawStage(hands){const canvas=$('#stage-hands'),r=$('#viewport').getBoundingClientRect();canvas.width=r.width;canvas.height=r.height;const c=canvas.getContext('2d');if(!$('#overlay-hands').checked||!enabled)return;const vw=$('#video').videoWidth||640,vh=$('#video').videoHeight||360,scale=Math.min(r.width/vw,r.height/vh),w=vw*scale,h=vh*scale,ox=(r.width-w)/2,oy=(r.height-h)/2;const edges=[[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17]];c.strokeStyle='#dcec6b';c.fillStyle='#f8ffe4';c.lineWidth=2;for(const hand of hands){for(const chain of edges){c.beginPath();chain.forEach((v,i)=>c[i?'lineTo':'moveTo'](ox+(1-hand[v].x)*w,oy+hand[v].y*h));c.stroke()}for(const p of hand){c.beginPath();c.arc(ox+(1-p.x)*w,oy+p.y*h,3,0,Math.PI*2);c.fill()}}}
$('#manipulation').onchange=()=>{manipulator.reset();lastPinch=lastSpread=null;$('#gesture-state').textContent=$('#manipulation').value==='trained'?'Trained mode: connect a model in ML Workspace':'Natural controls ready'};
const selector=$('#car-select');for(const c of cars){const option=document.createElement('option');option.value=c.id;option.textContent=c.name+' · '+c.year;selector.append(option)}
function selectCar(id){const c=cars.find(c=>c.id===id);$('#car-name').textContent=c.name;$('#car-team').textContent=c.team+' / '+c.year;$('#car-tag').textContent=c.id.toUpperCase()+' / '+c.year;$('#car-summary').textContent=c.summary;$('#car-source').href=c.source;$('#car-facts').replaceChildren();for(const [name,value]of c.facts){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;$('#car-facts').append(dt,dd)}if(!customAsset){paint.forEach(m=>m.color.set(c.color));if(accentMesh)accentMesh.material.color.set(c.accent)}all('.swatch').forEach(b=>b.classList.remove('selected'));}
selector.onchange=()=>{selectCar(selector.value);if(bundled)$('#stage-caption').textContent=selector.value==='qvist'?'QVIST 2026 CONCEPT · CC BY 4.0':'PROFILE DATA ONLY · VIEWING QVIST CONCEPT'};selectCar('qvist');
function disposeCustom(){if(!customAsset)return;for(const g of Object.values(groups)){car.remove(g);g.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose()}})}customAsset=false;bundled=false;systems={...originalSystems};renderComponents();groups={...proxyGroups};Object.values(groups).forEach(g=>{g.visible=true});$('#proxy').hidden=true;$('#model-file').value='';}
$('#proxy').onclick=()=>{disposeCustom();setExplode(0);$('#asset-status').textContent='Restored educational assembly.';$('#asset-note').textContent='Verified car data. Shared educational 3D proxy; not exact team geometry or internal CAD.';selectCar(selector.value)};
$('#model-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024){$('#asset-status').textContent='Choose a GLB smaller than 30 MB.';return}$('#asset-status').textContent='Loading local model…';try{const data=await file.arrayBuffer();const manager=new THREE.LoadingManager();manager.setURLModifier(url=>{if(url.startsWith('data:')||url.startsWith('blob:'))return url;throw Error('Only self-contained GLB assets are supported')});const gltf=await new GLTFLoader(manager).parseAsync(data,'');let invalid=false;gltf.scene.traverse(o=>{if(o.isSkinnedMesh||o.isInstancedMesh)invalid=true});if(invalid)throw Error('Use a static mesh GLB, without skeletal or instanced meshes');const bounds=new THREE.Box3().setFromObject(gltf.scene),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3()),factor=6/Math.max(size.x,size.y,size.z);if(!Number.isFinite(factor)||factor<=0)throw Error('Asset has no valid geometry');const modelRoot=new THREE.Group();modelRoot.add(gltf.scene);modelRoot.scale.setScalar(factor);modelRoot.position.set(-center.x*factor,-bounds.min.y*factor,-center.z*factor);modelRoot.updateMatrixWorld(true);const next={};for(const id of Object.keys(originalSystems)){next[id]=new THREE.Group();next[id].userData.system=id}gltf.scene.traverse(o=>{if(!o.isMesh)return;let names='',parent=o;while(parent){names+=' '+parent.name;parent=parent.parent}names=names.toLowerCase();const id=/wheel|tyre|tire|rim/.test(names)?'wheels':/suspension|wishbone|damper/.test(names)?'suspension':/radiator|cooling/.test(names)?'cooling':/engine|powerunit|gearbox|motor/.test(names)?'power':/wing|floor|diffuser/.test(names)?'aero':'body';const geo=o.geometry.clone().applyMatrix4(o.matrixWorld),src=Array.isArray(o.material)?o.material[0]:o.material;const mat=software?new THREE.MeshLambertMaterial({color:src.color||0xdddddd}):src.clone();next[id].add(new THREE.Mesh(geo,mat))});if(!Object.values(next).some(g=>g.children.length))throw Error('No static mesh found');disposeCustom();Object.values(proxyGroups).forEach(g=>g.visible=false);groups=next;Object.values(groups).forEach(g=>car.add(g));customAsset=true;$('#proxy').hidden=false;setExplode(0);selected=null;choose(null);$('#asset-note').textContent='Your local GLB. Car archive data describes the selected profile; asset accuracy is not verified.';const n=Object.values(groups).filter(g=>g.children.length).length;$('#asset-status').textContent=file.name+' · '+n+' named system groups. '+(n<2?'No separable internals in this asset.':'Component assignment inferred from mesh names; inspect before relying on it.');}catch(err){$('#asset-status').textContent='Could not load asset: '+err.message}};

function buildLabels(){const root=$('#component-labels');if(!root)return;root.replaceChildren();for(const [id,s]of Object.entries(systems)){const b=document.createElement('button');b.textContent=s[0];b.dataset.part=id;b.onclick=()=>choose(id);root.append(b)}}
function updateLabels(){if(!$('#component-labels'))return;for(const el of $('#component-labels').children){const g=groups[el.dataset.part];if(!showLabels||!g?.children.length){el.hidden=true;continue}if(!g.userData.labelCenter)g.userData.labelCenter=new THREE.Box3().setFromObject(g).getCenter(new THREE.Vector3()).applyMatrix4(g.matrixWorld.clone().invert());const p=g.localToWorld(g.userData.labelCenter.clone()).project(camera);el.hidden=p.z>1||Math.abs(p.x)>1||Math.abs(p.y)>1;el.style.left=(p.x*.5+.5)*100+'%';el.style.top=(-p.y*.5+.5)*100+'%';el.classList.toggle('selected',selected===el.dataset.part)}}
function flyTo(position,target){camera.position.copy(position);controls.target.copy(target);controls.update()}
all('[data-view]').forEach(b=>b.onclick=()=>{car.rotation.set(0,0,0);car.position.set(0,0,0);car.scale.setScalar(cameraActive?.8:1.2);const poses={perspective:[-9,6,10],side:[0,3,13],top:[0,14,.01]};flyTo(new THREE.Vector3(...poses[b.dataset.view]),new THREE.Vector3(0,.6,0));all('[data-view]').forEach(x=>x.classList.toggle('selected',x===b))});
$('#finish').onchange=e=>{finish=e.target.value;all('.swatch').forEach(b=>b.classList.remove('selected'))};
$('#labels').onclick=()=>{showLabels=!showLabels;$('#labels').classList.toggle('selected',showLabels)};
$('#wireframe').onclick=()=>{wireframe=!wireframe;$('#wireframe').classList.toggle('selected',wireframe)};
$('#isolate-part').onclick=()=>{if(!selected){$('#part-copy').textContent='Select a component first, then isolate it.';return}isolated=!isolated;$('#isolate-part').classList.toggle('selected',isolated)};
$('#show-all').onclick=()=>{endTour();isolated=false;selected=null;choose(null);$('#isolate-part').classList.remove('selected')};
$('#focus-part').onclick=()=>{if(!selected&&hovered){selected=hovered;showInspector(selected)}if(!selected)return;const g=groups[selected];const box=new THREE.Box3().setFromObject(g),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length(),direction=camera.position.clone().sub(controls.target).normalize();flyTo(center.clone().addScaledVector(direction,Math.max(4,size*1.4)),center)};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#viewport').requestFullscreen()}catch(e){$('#gesture-state').textContent='Fullscreen unavailable in this browser'}};
$('#camera-launch').onclick=()=>{$('#camera-settings').open=true;$('#camera').click();$('#viewport').scrollIntoView({behavior:'smooth',block:'center'})};
const tourOrder=['front-wing','chassis','left-sidepod','engine-cover','floor','rear-wing'];
function advanceTour(){const ids=bundled?tourOrder:Object.keys(systems);tourIndex=(tourIndex+1)%ids.length;selected=null;choose(ids[tourIndex]);setExplode(.45);$('#tour-step').hidden=false;$('#tour-next').hidden=false;$('#tour-step').textContent='GUIDED EXPLORATION / '+(tourIndex+1)+' OF '+ids.length;}
function endTour(){tourIndex=-1;$('#tour-step').hidden=true;$('#tour-next').hidden=true;$('#tour').textContent='Guided tour ↗'}
$('#tour').onclick=()=>{if(tourIndex>=0){endTour();return}tourIndex=-1;advanceTour();$('#tour').textContent='Exit tour ×'};$('#tour-next').onclick=advanceTour;
async function loadConcept(){try{let bytes;if(software){const r=await fetch('models/car-preview.glb');if(!r.ok)throw Error('Preview asset '+r.status);bytes=await r.arrayBuffer()}else{const r=await fetch('models/car.glb.gz');if(r.status===404){const preview=await fetch('models/car-preview.glb');if(!preview.ok)throw Error('Preview asset '+preview.status);bytes=await preview.arrayBuffer()}else{if(!r.ok)throw Error('Model asset '+r.status);bytes=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()}}const loaded=await new GLTFLoader().parseAsync(bytes,'');const box=new THREE.Box3().setFromObject(loaded.scene),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),factor=6.3/Math.max(size.x,size.y,size.z);const root=new THREE.Group();root.add(loaded.scene);root.scale.setScalar(factor);root.position.set(-center.x*factor,-box.min.y*factor,-center.z*factor);root.updateMatrixWorld(true);
const descriptions={
'front-wing':['Front wing','Layered wing elements redirect the incoming airflow. Inspect how the curved surfaces meet the nose and endplates.','AERODYNAMICS',[-1.4,.15,0]],
'chassis':['Nose & chassis','The central structure ties the nose, cockpit and rear body together. The model illustrates its outer form rather than its structural laminate.','STRUCTURE',[0,.2,0]],
'front-left-wheel':['Front left wheel','The tyre contact patch transmits braking and cornering forces. The visible mesh is an exterior assembly.','RUNNING GEAR',[-.15,.1,1.1]],
'front-right-wheel':['Front right wheel','Explore the wheel and tyre exterior. Tyre compound and temperature influence grip; this viewer does not simulate them.','RUNNING GEAR',[-.15,.1,-1.1]],
'front-suspension':['Front suspension','Links locate the front wheels and transfer forces to the chassis. Individual suspension settings are not provided by this concept asset.','VEHICLE DYNAMICS',[-.1,.6,0]],
'left-sidepod':['Left sidepod','This outer bodywork guides airflow beside the cockpit. Its display separation cut is illustrative; no full radiator assembly is included.','BODYWORK',[0,.5,1.1]],
'right-sidepod':['Right sidepod','The sidepod exterior is separable for inspection. It does not expose verified team cooling hardware.','BODYWORK',[0,.5,-1.1]],
'floor':['Floor & diffuser','Explore the underbody surface and rear diffuser shape. The actual pressure distribution would require aerodynamic analysis.','UNDERBODY',[0,-.25,0]],
'halo':['Halo','The cockpit protection structure surrounds the driver opening. This mesh illustrates its shape, not its certified material properties.','COCKPIT',[0,1.2,0]],
'engine-cover':['Airbox & engine cover','The raised air intake and removable outer cover form the visible powertrain enclosure. The source does not contain a complete engine underneath.','BODYWORK',[.3,1.5,0]],
'rear-suspension':['Rear suspension','The rear linkage connects the chassis and rear wheel assemblies. Inspect the relationship of its visible members.','VEHICLE DYNAMICS',[.2,.5,0]],
'rear-left-wheel':['Rear left wheel','Rear tyre and wheel exterior, displayed as one assembly. Pull it outward to inspect the surrounding running gear.','RUNNING GEAR',[.2,.1,1.1]],
'rear-right-wheel':['Rear right wheel','Rear wheel assembly. Exploded positions are educational display offsets rather than service instructions.','RUNNING GEAR',[.2,.1,-1.1]],
'rear-wing':['Rear wing','Layered rear wing surfaces provide an aerodynamic load. Inspect the elements and endplates from the side and top.','AERODYNAMICS',[1.3,.8,0]],
'mirrors':['Mirrors','Small exterior mirror housings sit alongside the cockpit. Their supports also interact with the passing airflow.','COCKPIT',[0,.7,.1]],
'exhaust':['Exhaust outlet','The visible outlet marks the rearward path of exhaust gases. There is no complete internal engine model attached to it.','POWERTRAIN EXTERIOR',[1.1,.4,0]]};
const next={},nextSystems={};for(const [id,d]of Object.entries(descriptions)){next[id]=new THREE.Group();next[id].userData={system:id,offset:d[3]};nextSystems[id]=d.slice(0,3)}
loaded.scene.traverse(o=>{if(!o.isMesh)return;let ancestor=o;while(ancestor&&!next[ancestor.name])ancestor=ancestor.parent;if(!ancestor)throw Error('Unmapped concept mesh '+o.name);const geo=o.geometry.clone().applyMatrix4(o.matrixWorld);const src=Array.isArray(o.material)?o.material[0]:o.material;const m=software?new THREE.MeshLambertMaterial({color:/chassis|sidepod|engine-cover/.test(ancestor.name)?0xc33429:/wheel/.test(ancestor.name)?0x20272d:0x56636b}):src.clone();m.vertexColors=false;m.side=THREE.DoubleSide;const mesh=new THREE.Mesh(geo,m);mesh.castShadow=true;next[ancestor.name].add(mesh)});disposeCustom();Object.values(proxyGroups).forEach(g=>g.visible=false);groups=next;systems=nextSystems;customAsset=true;bundled=true;Object.values(groups).forEach(g=>car.add(g));paint=[];for(const g of Object.values(groups))g.traverse(o=>{if(o.isMesh&&['chassis','left-sidepod','right-sidepod','engine-cover'].includes(g.userData.system))paint.push(o.material)});renderComponents();car.scale.setScalar(cameraActive?.8:1.2);selected=null;choose(null);$('#proxy').hidden=true;$('#asset-note').textContent='Qvist 2026 concept. Detailed exterior; illustrative seams. No complete internal engine. Team profiles change reference data, not this geometry.';$('#asset-status').textContent=software?'Silhouette proxy: software rendering loses cavities and small details.':'Full-detail licensed model loaded.';$('#stage-caption').textContent=software?'SIMPLIFIED SILHOUETTE · QVIST CONCEPT':'QVIST 2026 CONCEPT · CC BY 4.0';$('#asset-loading').hidden=true;}catch(e){$('#asset-loading').textContent='Detailed model unavailable · educational fallback active';$('#asset-status').textContent=e.message}}
loadConcept();
